const upsertAssetDerivative = `-- name: UpsertAssetDerivative :one
INSERT INTO asset_derivatives (workspace_id, asset_id, kind, r2_key, content_type, size_bytes, meta)
VALUES ($1, $2, $3, $4, $5, $6, $7)
ON CONFLICT (asset_id, kind) DO UPDATE
SET r2_key = EXCLUDED.r2_key, content_type = EXCLUDED.content_type, size_bytes = EXCLUDED.size_bytes, meta = EXCLUDED.meta
WHERE asset_derivatives.workspace_id = EXCLUDED.workspace_id
RETURNING id, workspace_id, asset_id, kind, r2_key, content_type, size_bytes, meta, created_at, updated_at
`

type UpsertAssetDerivativeParams struct {
	WorkspaceID ids.WorkspaceID
	AssetID     ids.AssetID
	Kind        string
	R2Key       string
	ContentType string
	SizeBytes   int64
	Meta        json.RawMessage
}

func (q *Queries) UpsertAssetDerivative(ctx context.Context, arg UpsertAssetDerivativeParams) (AssetDerivative, error) {
	row := q.db.QueryRow(ctx, upsertAssetDerivative,
		arg.WorkspaceID,
		arg.AssetID,
		arg.Kind,
		arg.R2Key,
		arg.ContentType,
		arg.SizeBytes,
		arg.Meta,
	)
	var i AssetDerivative
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.AssetID,
		&i.Kind,
		&i.R2Key,
		&i.ContentType,
		&i.SizeBytes,
		&i.Meta,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
